function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  let centerX = W / 2;
  let centerY = H / 2;
  let radius = Math.min(W, H) / 4;
  let numCircles = 10;
  let angleStep = 2 * Math.PI / numCircles;

  for (let i = 0; i < numCircles; i++) {
    let angle = i * angleStep + Math.sin(t + i) * Math.PI / 4;
    let x = centerX + Math.cos(angle) * radius;
    let y = centerY + Math.sin(angle) * radius;

    ctx.beginPath();
    ctx.arc(x, y, 20, 0, 2 * Math.PI);
    ctx.stroke();

    let mergeRadius = 10 + Math.abs(Math.sin(t + i * 2)) * 20;
    ctx.beginPath();
    ctx.arc(centerX, centerY, mergeRadius, angle - Math.PI / 4, angle + Math.PI / 4);
    ctx.stroke();
  }

  ctx.restore();
}
